import './ProductGrid.css';

export interface Product {
  id: string;
  name: string;
  price: number;
  imageUrl?: string;
}

interface ProductGridProps {
  products: Product[];
  status: 'loading' | 'loaded';
}

const GHOST_COUNT = 6;

export function ProductGrid({ products, status }: ProductGridProps): JSX.Element {
  if (status === 'loading') {
    return (
      <ul role="list" className="product-grid">
        {Array.from({ length: GHOST_COUNT }, (_, i) => (
          <li key={i} className="product-grid-ghost" aria-label="Loading product" />
        ))}
      </ul>
    );
  }

  return (
    <ul role="list" className="product-grid">
      {products.map((product) => (
        <li key={product.id} className="product-grid-item">
          {product.imageUrl && (
            <img src={product.imageUrl} alt={product.name} className="product-grid-image" />
          )}
          <span className="product-grid-name">{product.name}</span>
          <span className="product-grid-price">{product.price}</span>
        </li>
      ))}
    </ul>
  );
}

