import { useState } from 'react';
import './ChipBar.css';

interface ChipBarProps {
  statuses: string[];
}

// Owns only visual pressed state; grid filtering is not wired.
export function ChipBar({ statuses }: ChipBarProps): JSX.Element {
  const [selected, setSelected] = useState<Set<string>>(new Set());

  function handleClick(status: string): void {
    const next = new Set(selected);
    if (next.has(status)) {
      next.delete(status);
    } else {
      next.add(status);
    }
    setSelected(next);
  }

  return (
    <ul role="list" className="chip-bar">
      {statuses.map((status) => (
        <li key={status} className="chip-bar-item">
          <button
            type="button"
            className="chip"
            aria-pressed={selected.has(status)}
            onClick={() => handleClick(status)}
          >
            {status}
          </button>
        </li>
      ))}
    </ul>
  );
}

